package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 接续登记请求：在两趟已发布计划间建立接续保障关系。
 * requestKey 为幂等键；guaranteeMinutes 合法范围 0~720（越界返回 422）；
 * crossMidnight 为 true 表示明确跨零点接续（后车运营日 = 前车运营日 + 1）。
 */
public record RegisterConnectionRequest(
        @NotBlank String requestKey,
        @NotBlank String predecessorScheduleKey,
        @NotBlank String successorScheduleKey,
        @NotNull Integer guaranteeMinutes,
        boolean crossMidnight) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;

/**
 * 批量保障改签请求：对选定的一组 CONNECTION_AT_RISK 后车计划，
 * 在同一事务内整体延后至同时满足线路时隙与全部接续分钟数的时刻；
 * 任一计划找不到不冲突时间窗则整次 422 回滚。requestKey 为幂等键。
 */
public record GuaranteeRescheduleRequest(
        @NotBlank String requestKey,
        @NotNull @Size(min = 1, max = 30) List<@NotBlank String> scheduleKeys) {
}

package com.example.starter.plan.web.dto;

import java.time.Instant;

/**
 * 批量保障改签单计划结果：记录原/新始发时刻与实际平移分钟数。
 */
public record GuaranteeRescheduleItem(
        String scheduleKey,
        int version,
        Instant previousDepartureUtc,
        Instant newDepartureUtc,
        long shiftMinutes,
        String riskStatus) {
}

package com.example.starter.plan.web.dto;

import java.util.List;

/**
 * 批量保障改签响应：全部成功才提交，items 顺序与请求 scheduleKeys 一致。
 */
public record GuaranteeRescheduleResponse(List<GuaranteeRescheduleItem> items) {
}

package com.example.starter.plan.web.dto;

/**
 * 单条生效接续的实时保障评估（诊断用）。
 * sufficient = deficitMinutes &lt;= 0，即实际接续分钟数满足要求。
 */
public record ConnectionDeficitView(
        long connectionId,
        String predecessorScheduleKey,
        int guaranteeMinutes,
        long actualMinutes,
        long deficitMinutes,
        boolean sufficient) {
}

package com.example.starter.plan.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 计划接续风险诊断视图：当前风险标记、可选改签时间窗（仅风险存续期非空）
 * 及全部生效接续的实时保障评估。只读，不改变任何状态。
 */
public record ConnectionRiskView(
        String scheduleKey,
        String riskStatus,
        Instant windowStartUtc,
        Instant windowEndUtc,
        List<ConnectionDeficitView> inboundConnections) {
}

